/*
 * prog35_perfect_numbers
 *
 * The original binary implements a small command‑line utility that
 * classifies a positive integer as *deficient*, *perfect* or *abundant*
 * based on the sum of its proper divisors.  It also handles a few error
 * conditions that were discovered in the decompiled state‑machine:
 *
 *   - No command‑line argument      → prints "NO_INPUT"
 *   - Argument not a valid integer → prints "BAD_INPUT"
 *   - Integer ≤ 0                  → prints "BAD_INPUT"
 *   - Integer > 1 000 000          → prints "OUT_OF_RANGE"
 *
 * For a valid input `n` (1 ≤ n ≤ 1 000 000) the program computes the sum
 * of all proper divisors of `n` (i.e. all positive integers `< n` that
 * divide `n` exactly) and prints the result together with the classification:
 *
 *     n=%ld sum=%ld deficient\n
 *     n=%ld sum=%ld perfect\n
 *     n=%ld sum=%ld abundant\n
 *
 * The behaviour matches the observable output of the original binary,
 * while the control‑flow has been rewritten in a clear, idiomatic style.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    long n;          /* the input number */
    char *endptr;    /* used by strtol */
    long sum = 0;    /* sum of proper divisors */

    /* -----------------------------------------------------------------
     *  Error handling – missing argument
     * ----------------------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Parse the argument as a base‑10 integer.
     *  strtol sets endptr to the first character that is not part of the
     *  number.  If no conversion happens, or if there are leftover
     *  characters, the input is considered bad.
     * ----------------------------------------------------------------- */
    errno = 0;
    n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  The original program treats non‑positive numbers as bad input.
     * ----------------------------------------------------------------- */
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Upper bound check – the original binary limits the range to
     *  1 000 000.
     * ----------------------------------------------------------------- */
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     *  Compute the sum of proper divisors of n.
     *  The naïve O(n) loop matches the behaviour of the decompiled code.
     * ----------------------------------------------------------------- */
    for (long d = 1; d < n; ++d) {
        if (n % d == 0) {
            sum += d;
        }
    }

    /* -----------------------------------------------------------------
     *  Classification based on the relationship between sum and n.
     * ----------------------------------------------------------------- */
    if (sum < n) {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    } else if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    }

    return 0;
}
